mapper.select:
/* com.portal.security.groupauthority.AuthorGroupMapper.selectAuthorGroupList */ SELECT a.USER_ID AS userId, a.USER_NM AS userNm, a.GROUP_ID AS groupId, a.MBER_TY_CODE AS mberTyCode, ( SELECT c.CODE_NM FROM LETTCCMMNDETAILCODE c WHERE c.CODE_ID = 'COM012' AND c.CODE = a.MBER_TY_CODE AND c.USE_AT = 'Y' ) AS mberTyNm, b.AUTHOR_CODE AS authorCode, (CASE WHEN b.SCRTY_DTRMN_TRGET_ID IS NULL THEN 'N' ELSE 'Y' END) AS regYn, a.ESNTL_ID AS uniqId FROM ( SELECT MBER_ID AS USER_ID, MBER_NM AS USER_NM, GROUP_ID, 'USR01' AS MBER_TY_CODE, ESNTL_ID FROM LETTNGNRLMBER UNION ALL SELECT ENTRPRS_MBER_ID AS USER_ID, CMPNY_NM AS USER_NM, GROUP_ID, 'USR02' AS MBER_TY_CODE, ESNTL_ID FROM LETTNENTRPRSMBER UNION ALL SELECT EMPLYR_ID AS USER_ID, USER_NM AS USER_NM, GROUP_ID, 'USR03' AS MBER_TY_CODE, ESNTL_ID FROM LETTNEMPLYRINFO ) a LEFT OUTER JOIN LETTNEMPLYRSCRTYESTBS b ON a.ESNTL_ID = b.SCRTY_DTRMN_TRGET_ID WHERE 1 = 1
AND a.USER_ID LIKE CONCAT('%', #{searchKeyword}, '%')
AND a.USER_NM LIKE CONCAT('%', #{searchKeyword}, '%')
AND a.GROUP_ID = #{searchKeyword}
LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

mapper.insert:
/* com.portal.security.groupauthority.AuthorGroupMapper.insertAuthorGroup */
INSERT INTO LETTNEMPLYRSCRTYESTBS
(
	SCRTY_DTRMN_TRGET_ID, MBER_TY_CODE, AUTHOR_CODE
)
VALUES
(
	#{uniqId}, #{mberTyCode}, #{authorCode}
)

mapper.update:
/* com.portal.security.groupauthority.AuthorGroupMapper.updateAuthorGroup */
UPDATE LETTNEMPLYRSCRTYESTBS
   SET MBER_TY_CODE = #{mberTyCode},
       AUTHOR_CODE  = #{authorCode}
 WHERE SCRTY_DTRMN_TRGET_ID = #{uniqId}

mapper.select:
/* com.portal.security.groupauthority.AuthorGroupMapper.selectAuthorGroupListTotCnt */ SELECT COUNT(*) AS totcnt FROM ( SELECT MBER_ID AS USER_ID, MBER_NM AS USER_NM, GROUP_ID, 'USR01' AS MBER_TY_CODE, ESNTL_ID FROM LETTNGNRLMBER UNION ALL SELECT ENTRPRS_MBER_ID AS USER_ID, CMPNY_NM AS USER_NM, GROUP_ID, 'USR02' AS MBER_TY_CODE, ESNTL_ID FROM LETTNENTRPRSMBER UNION ALL SELECT EMPLYR_ID AS USER_ID, USER_NM AS USER_NM, GROUP_ID, 'USR03' AS MBER_TY_CODE, ESNTL_ID FROM LETTNEMPLYRINFO ) a LEFT OUTER JOIN LETTNEMPLYRSCRTYESTBS b ON a.ESNTL_ID = b.SCRTY_DTRMN_TRGET_ID WHERE 1 = 1
AND a.USER_ID LIKE CONCAT('%', #{searchKeyword}, '%')
AND a.USER_NM LIKE CONCAT('%', #{searchKeyword}, '%')
AND a.GROUP_ID = #{searchKeyword}
